function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10,000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each value of nums is an integer from 0 to 10,000.';
  if (!Number.isInteger(k) || k < 0 || k > 10000) return 'k is an integer from 0 to 10,000.';
  return null;
}

