function smallestRangeII(nums, k) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  let best = nums[n - 1] - nums[0];

  for (let i = 0; i < n - 1; i++) {
    const high = Math.max(nums[i] + k, nums[n - 1] - k);
    const low = Math.min(nums[0] + k, nums[i + 1] - k);
    best = Math.min(best, high - low);
  }
  return best;
}

