function smallestRangeII(nums, k) {
  // Try every possible final minimum; each element then takes its smallest option that is not below it.
  let best = Infinity;
  for (const floor of nums.flatMap(v => [v - k, v + k])) {
    let max = -Infinity;
    let min = Infinity;
    let feasible = true;
    for (const v of nums) {
      const value = v - k >= floor ? v - k : v + k >= floor ? v + k : null;
      if (value === null) { feasible = false; break; }
      max = Math.max(max, value);
      min = Math.min(min, value);
    }
    if (feasible) best = Math.min(best, max - min);
  }
  return best;
}

