  const n = 1 + Math.floor(rand() * 9);
  const span = [3, 10, 30, 10000][Math.floor(rand() * 4)];
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (span + 1)));
  const pick = rand();
  const k = pick < 0.15 ? 0 : pick < 0.3 ? 10000 : Math.floor(rand() * (Math.min(span, 10000) + 1));
